func cmdRoadmapCheck(root string, args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		return usageError(stderr, "Usage: pose roadmap-check <slug> [--strict|--tolerant] [--json]")
	}
	slug := args[0]
	strict, jsonOutput := true, false
	for _, arg := range args[1:] {
		switch arg {
		case "--strict":
			strict = true
		case "--tolerant":
			strict = false
		case "--json":
			jsonOutput = true
		default:
			return usageError(stderr, "Usage: pose roadmap-check <slug> [--strict|--tolerant] [--json]")
